fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    let rows = y.len();
    let cols = x.len();

    // Construct the first output matrix:
    // each row is a copy of x
    let x_mesh: Vec<Vec<f32>> = (0..rows)
        .map(|_| x.clone())
        .collect();

    // Construct the second output matrix:
    // each row is y[i] repeated cols times
    let y_mesh: Vec<Vec<f32>> = y.iter()
        .map(|&y_val| vec![y_val; cols])
        .collect();

    (x_mesh, y_mesh)
}